#include "research.hpp"
#include <iostream>
#include <fstream>
#include <stdexcept>
void require(bool value,const char* text){if(!value)throw std::runtime_error(text);}
int main(){try{
 const auto root=std::filesystem::current_path()/"research-test-data";std::filesystem::create_directories(root);
 life::NativeSimulation world(32,24,.2,500,53,17);world.seedBenchmarkMovers(25);auto frozen=world.freeze();require(bool(frozen),"Small world exceeded capture budget");const auto base=world.stateDigest();world.step(4);require(frozen->stateDigest()==base,"Frozen state changed with live world");
 const auto genome=world.genomeRecord(world.organisms().front().id);auto altered=genome;altered.name="Test specimen";altered.genes.resistance=.5;const auto changes=life::NativeSimulation::compareGenomes(genome,altered);require(!changes.traits.empty()&&changes.changedWeights==0,"Genome trait comparison failed");const auto path=root/"specimen.lfegenome";if(std::filesystem::exists(path))std::filesystem::remove(path);life::NativeSimulation::saveGenome(altered,path);const auto loaded=life::NativeSimulation::loadGenome(path);require(loaded.name==altered.name&&loaded.genes==altered.genes,"Genome roundtrip failed");bool refused=false;try{life::NativeSimulation::saveGenome(altered,path);}catch(...){refused=true;}require(refused,"Genome overwrite was silent");
 auto imported=world.freeze();int introduced=-1;for(int y=0;y<24&&introduced<0;++y)for(int x=0;x<32&&introduced<0;++x)introduced=imported->introduceGenome(loaded,x,y,path.string());require(introduced>=0,"No specimen introduced");require(imported->inspect(introduced)->parentId==-1,"Import fabricated ancestry");
 life::ResearchSuite::Limits limits;limits.interval=30;limits.ram=16*1024*1024;limits.disk=64*1024*1024;life::ResearchSuite suite(root/"suite",limits);life::NativeSimulation running(32,24,.2,500,53,17);running.seedBenchmarkMovers(25);suite.attach(running);suite.waitIdle();require(suite.snapshot()->checkpoints.size()==1,"Initial checkpoint missing");running.step(10);running.paintResource(0,0,life::ResourceType::Plant,777);running.step(10);const auto at20=running.stateDigest();running.step(10);suite.observe(running);suite.waitIdle();running.step(10);suite.observe(running);const auto present=running.stateDigest();suite.seek(running,20);suite.waitIdle();require(suite.observe(running)&&running.tickCount()==20&&running.stateDigest()==at20,"Rewind command replay differs");require(suite.preview(),"Seek did not enter read-only preview");suite.returnToPresent();suite.waitIdle();require(suite.observe(running)&&running.stateDigest()==present&&!suite.preview(),"Return to present lost state");
 suite.seek(running,20);suite.waitIdle();suite.observe(running);suite.branch(running,"Alternative");suite.waitIdle();suite.observe(running);require(suite.snapshot()->branches.size()==2&&!suite.preview(),"Branch did not activate");running.paintResource(1,1,life::ResourceType::Carrion,999);running.step(5);suite.observe(running);const auto alternative=running.stateDigest();suite.activate(running,1);suite.waitIdle();suite.observe(running);require(running.stateDigest()==present,"Original branch was changed");suite.activate(running,2);suite.waitIdle();suite.observe(running);require(running.stateDigest()==alternative,"Inactive branch head was lost");
 suite.experiment(running,12,{0,0,life::CommandKind::Resource,0,0,int(life::ResourceType::Plant),1234});suite.waitIdle();suite.observe(running);require(suite.snapshot()->branches.size()==4,"Paired experiment did not retain both arms");const auto& branches=suite.snapshot()->branches;require(branches[2].tick==branches[3].tick,"Experiment arms used unequal tick counts");suite.saveSpecimen(running,running.organisms().front().id,"Specimen","Notes");suite.waitIdle();require(!suite.snapshot()->library.empty(),"Library did not refresh");
 const auto keep=running.stateDigest();suite.seek(running,20);suite.cancel();suite.waitIdle();suite.observe(running);require(running.stateDigest()==keep,"Cancelled seek changed the world");
 life::ResearchSuite::Limits tiny;tiny.ram=1;tiny.disk=4096;life::ResearchSuite limited(root/"limited",tiny);limited.attach(running);limited.waitIdle();require(limited.snapshot()->checkpoints.empty(),"Memory limit did not skip capture");require(running.stateDigest()==keep,"Capture limit changed physics");std::cout<<"Frozen states, genome files, exact rewind, branches, experiments, library and limits passed\n";
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
